Running command: cd /workspace && python3 << 'EOF'
data = open('repo-vul/src-vul/afl/testcases/images/jpeg/not_kitty.jpg','rb').read()
# Extract DQT and DHT tables
i = 0
tables = {}
while i < len(data)-1:
    if data[i] == 0xFF:
        m = data[i+1]
        if m == 0xD8:
            i += 2
        elif m == 0xD9:
            break
        elif m in (0x01, 0xD0, 0xD1, 0xD2, 0xD3, 0xD4, 0xD5, 0xD6, 0xD7):
            i += 2
        else:
            ln = (data[i+2]<<8) | data[i+3]
            if m in (0xDB, 0xC4):
                tables.setdefault(m, []).append(bytes(data[i:i+2+ln]))
            i += 2 + ln
    else:
        i += 1

for m, t in tables.items():
    print(f'marker 0x{m:02x}: {len(t)} tables')
    for j, tb in enumerate(t):
        print(f'  table {j}: len={len(tb)}')
        # Save
        open(f'/workspace/table_{m:02x}_{j}.bin','wb').write(tb)
EOF

